net.coobird.thumbnailator.util.exif.IfdStructure offsetIfd = new net.coobird.thumbnailator.util.exif.IfdStructure(0x0112, 3, 3, 120);
boolean isOffsetOffset = offsetIfd.isOffset();

assert !isInlineOffset : "2-byte payload (SHORT x 1) should be inline, not an offset";
assert isOffsetOffset : "6-byte payload (SHORT x 3) should be an offset";

System.out.println("__CHECK__ isOffset " + isInlineOffset + "_" + isOffsetOffset);

